{"command":"cd /workspace && python3 - << 'PY'
# Build pattern data. 64 rows per pattern, 8 channels. 135 BPM, speed 6 => 16 rows per beat? speed ticks.
# We will create 4 patterns: intro, build, drop/main, break. Loop from end back to pattern index 8? loop_start 8 means restart at order pos 8.
# Let's make song length 24 positions, orders 0-3 intro/build/drop/break, then repeat. Set loop_start to position 8 (i.e. pattern 2 main) for continuous loop.
# Actually FT2 loop_start sets restart position in orders. We'll use 24 orders: 0,1,2,3,0,1,2,3,2,3,2,3,2,2,2,2,2,3,2,3,2,3,2,3 and loop_start=8 so it loops main/break.
# But for a keygen, simpler: orders 0,1,2,3 repeated, loop_start=4. Let's do 8 orders: intro(0), build(1), drop(2), break(3), then 2,3 repeated.
# I'll generate notes programmatically.

notes = {
    'C-':0,'C#':1,'D-':2,'D#':3,'E-':4,'F-':5,'F#':6,'G-':7,'G#':8,'A-':9,'A#':10,'B-':11
}
oct = lambda n,o: notes[n] + (o+1)*12  # note values for FT2 (C-0=0? Actually C-0=0, but sample relative_note can shift)
# Use sample relative_note set to 0, so note value maps directly.

# Pattern layout channels:
# 0 kick
# 1 snare
# 2 hihat
# 3 bass
# 4 lead
# 5 pad chords
# 6 arp
# 7 lead echo/FX

patterns = []

# Pattern 0: intro (kick + hihat + pad + bass sparse)
def pat_intro():
    rows=[]
    for r in range(64):
        row=[None]*8
        # kick on 0,16,32,48
        if r in (0,16,32,48):
            row[0]=(1, 'C-3', 64)  # instrument, note, vol
        # hihat offbeats 8,24,40,56
        if r in (8,24,40,56):
            row[2]=(3,'C-4',36)
        # pad chord every 16
        if r in (0,32):
            row[5]=(6,'C-4',32)
        if r in (16,48):
            row[5]=(6,'G-3',32)
        # bass sparse
        if r in (0,8,16,24,32,40,48,56):
            note = 'C-2' if r%16 in (0,1) else 'G-1'
            row[3]=(4,note,40)
        rows.append(row)
    return rows

# Pattern 1: build (add snare rolls, more hihat, arp enters)
def pat_build():
    rows=[]
    for r in range(64):
        row=[None]*8
        if r in (0,16,32,48):
            row[0]=(1,'C-3',64)
        if r in (8,24,40,56):
            row[1]=(2,'C-4',44)
        if r%4==2:
            row[2]=(3,'C-5',32)
        # arp on 8ths
        if r%4==0:
            arp_notes=['C-5','E-5','G-5','A#5','C-6','G-5','E-5','C-5']
            row[6]=(7, arp_notes[(r//4)%8], 28)
        # bass every 4 steps
        if r%4==0:
            row[3]=(4, 'C-2' if r%16==0 else 'G-1', 44)
        if r in (0,32):
            row[5]=(6,'C-4',36)
        if r in (16,48):
            row[5]=(6,'G-3',36)
        rows.append(row)
    return rows

# Pattern 2: drop/main (full beat, bassline, lead melody, pad, arp)
def pat_drop():
    rows=[]
    for r in range(64):
        row=[None]*8
        # kick four-on-floor
        if r%4==0:
            row[0]=(1,'C-3',64)
        # snare backbeat
        if r%8==4:
            row[1]=(2,'C-4',48)
        # hihat 16ths
        if r%2==0:
            row[2]=(3,'C-5',34)
        # bassline: C,F,G,A# maybe? C-2, F-1, G-1, A#1
        bassline=[('C-2',0),('C-2',2),('F-1',4),('F-1',6),('G-1',8),('G-1',10),('A#1',12),('A#1',14)]
        for note,off in bassline:
            if r%16==off:
                row[3]=(4,note,48)
        # pad chord changes
        if r==0:
            row[5]=(6,'C-4',36)
        if r==16:
            row[5]=(6,'F-3',36)
        if r==32:
            row[5]=(6,'G-3',36)
        if r==48:
            row[5]=(6,'A#3',34)
        # lead melody (16th notes simple)
        lead_rows={0:('C-5',56),4:('E-5',54),8:('G-5',56),12:('A#5',54),16:('A-5',56),20:('F-5',54),24:('G-5',56),28:('E-5',54),32:('C-5',56),36:('D-5',54),40:('E-5',56),44:('G-5',54),48:('F-5',56),52:('D-5',54),56:('C-5',56),60:('G-4',52)}
        if r in lead_rows:
            row[4]=(5,lead_rows[r][0],lead_rows[r][1])
        # arp rapid 8ths
        if r%2==0:
            arp=['C-6','E-6','G-6','C-7','E-7','C-7','G-6','E-6']
            row[6]=(7, arp[(r//2)%8], 26)
        # lead echo channel (same melody delayed 1/16 sometimes with lower vol)
        if r in lead_rows and (r+2)%4==0:
            row[7]=(5,lead_rows[r][0],lead_rows[r][1]-10)
        rows.append(row)
    return rows

# Pattern 3: break/ variation (half beat, fill, pad)
def pat_break():
    rows=[]
    for r in range(64):
        row=[None]*8
        if r in (0,8,16,24,32,40,48,56):
            row[0]=(1,'C-3',62)
        if r in (4,20,36,52):
            row[1]=(2,'C-4',46)
        if r%4==2:
            row[2]=(3,'C-5',32)
        # bass sustain notes
        if r in (0,32):
            row[3]=(4,'C-2',44)
        if r==16:
            row[3]=(4,'G-1',44)
        if r==48:
            row[3]=(4,'A#1',44)
        if r in (0,16,32,48):
            row[5]=(6,'C-4',34)
        # lead sustains
        if r in (0,16,32,48):
            row[4]=(5,'C-5',50)
        if r in (8,24,40,56):
            row[4]=(5,'G-5',48)
        # arp every 4
        if r%4==0:
            arp=['C-6','E-6','G-6','B-6']
            row[6]=(7,arp[(r//4)%4],24)
        rows.append(row)
    return rows

patterns = [pat_intro(), pat_build(), pat_drop(), pat_break()]

# Convert to ft2 batch calls
calls=[]
for pi,pat in enumerate(patterns):
    for ri,row in enumerate(pat):
        for ci,cell in enumerate(row):
            if cell:
                ins,note,vol=cell
                calls.append({"name":"pattern_set_cell","arguments":{"pattern":pi,"row":ri,"channel":ci,"note":note,"instrument":ins,"volume":vol}})

# Orders 0-7: 0,1,2,3,2,3,2,3 then loop_start=4
for i in range(8):
    order = [0,1,2,3,2,3,2,3][i]
    calls.append({"name":"order_set","arguments":{"position":i,"pattern":order}})
calls.append({"name":"song_set","arguments":{"loop_start":4,"length":8,"bpm":135,"speed":6,"channels":8}})

with open('pattern_data.json','w') as f:
    json.dump(calls,f)
print('calls', len(calls))
PY"}

