notes = {'C-':0,'C#':1,'D-':2,'D#':3,'E-':4,'F-':5,'F#':6,'G-':7,'G#':8,'A-':9,'A#':10,'B-':11}
def oct(n,o): return notes[n] + (o+1)*12
def N(name):
    return oct(name[:2], int(name[2:]))

def pat_intro():
