    for r in range(64):
        row=[None]*8
        if r in (0,16,32,48): row[0]=(1,N('C-3'),64)
        if r in (8,24,40,56): row[2]=(3,N('C-5'),36)
        if r in (0,32): row[5]=(6,N('C-4'),32)
        if r in (16,48): row[5]=(6,N('G-3'),32)
        if r in (0,8,16,24,32,40,48,56):
            note=N('C-2') if r%16 in (0,1) else N('G-1')
            row[3]=(4,note,40)
        rows.append(row)
    return rows

def pat_build():
    rows=[]
    for r in range(64):
        row=[None]*8
        if r in (0,16,32,48): row[0]=(1,N('C-3'),64)
        if r in (8,24,40,56): row[1]=(2,N('C-4'),44)
        if r%4==2: row[2]=(3,N('C-6'),32)
        if r%4==0:
            arp=[N('C-5'),N('E-5'),N('G-5'),N('A#5'),N('C-6'),N('G-5'),N('E-5'),N('C-5')]
            row[6]=(7,arp[(r//4)%8],28)
        if r%4==0: row[3]=(4,N('C-2') if r%16==0 else N('G-1'),44)
        if r in (0,32): row[5]=(6,N('C-4'),36)
        if r in (16,48): row[5]=(6,N('G-3'),36)
        rows.append(row)
    return rows

def pat_drop():
    rows=[]
    for r in range(64):
        row=[None]*8
        if r%4==0: row[0]=(1,N('C-3'),64)
        if r%8==4: row[1]=(2,N('C-4'),48)
        if r%2==0: row[2]=(3,N('C-6'),34)
        bass=[(N('C-2'),0),(N('C-2'),2),(N('F-1'),4),(N('F-1'),6),(N('G-1'),8),(N('G-1'),10),(N('A#1'),12),(N('A#1'),14)]
        for note,off in bass:
            if r%16==off: row[3]=(4,note,48)
        if r==0: row[5]=(6,N('C-4'),36)
        if r==16: row[5]=(6,N('F-3'),36)
        if r==32: row[5]=(6,N('G-3'),36)
        if r==48: row[5]=(6,N('A#3'),34)
        lead={0:(N('C-5'),56),4:(N('E-5'),54),8:(N('G-5'),56),12:(N('A#5'),54),16:(N('A-5'),56),20:(N('F-5'),54),24:(N('G-5'),56),28:(N('E-5'),54),32:(N('C-5'),56),36:(N('D-5'),54),40:(N('E-5'),56),44:(N('G-5'),54),48:(N('F-5'),56),52:(N('D-5'),54),56:(N('C-5'),56),60:(N('G-4'),52)}
        if r in lead: row[4]=(5,lead[r][0],lead[r][1])
        if r%2==0:
            arp=[N('C-6'),N('E-6'),N('G-6'),N('C-6'),N('E-6'),N('C-6'),N('G-5'),N('E-5')]
            row[6]=(7,arp[(r//2)%8],26)
        if r in lead and (r+2)%4==0: row[7]=(5,lead[r][0],max(10,lead[r][1]-12))
        rows.append(row)
    return rows

def pat_break():
    rows=[]
