        if r in (4,20,36,52): row[1]=(2,N('C-4'),46)
        if r%4==2: row[2]=(3,N('C-6'),32)
        if r in (0,32): row[3]=(4,N('C-2'),44)
        if r==16: row[3]=(4,N('G-1'),44)
        if r==48: row[3]=(4,N('A#1'),44)
        if r in (0,16,32,48): row[5]=(6,N('C-4'),34)
        if r in (0,16,32,48): row[4]=(5,N('C-5'),50)
        if r in (8,24,40,56): row[4]=(5,N('G-5'),48)
        if r%4==0:
            arp=[N('C-5'),N('E-5'),N('G-5'),N('B-5')]
            row[6]=(7,arp[(r//4)%4],24)
        rows.append(row)
    return rows

patterns=[pat_intro(),pat_build(),pat_drop(),pat_break()]
